def mark_copies(apps, schema_editor):
    """Marks every recipe still linked to its original as a Copy, and moves a catalogue original's source credit off
    each copy of it into the copy's read-only credit. A copy whose original was already deleted can't be told apart."""
    Recipe = apps.get_model('recipes', 'Recipe')
    Recipe.objects.filter(adapted_from__isnull=False).update(is_copy=True)
    of_the_catalogue = Recipe.objects.filter(adapted_from__isnull=False, adapted_from__household__isnull=True)
    copies = list(of_the_catalogue.select_related('adapted_from'))
    for copy in copies:
        original = copy.adapted_from
        copy.original_source, copy.original_source_url = original.source, original.source_url
        # A credit the household changed is theirs, so only the one copied unchanged moves.
        if (copy.source, copy.source_url) == (original.source, original.source_url):
            copy.source, copy.source_url = '', ''
    Recipe.objects.bulk_update(copies, ['original_source', 'original_source_url', 'source', 'source_url'])


